#!/usr/bin/env bash
set -Eeuo pipefail

VERSION="3.0.0"
REV="MASTER-GROUNDUP-2"
APP_VERSION="NOVA-3.0.0-MASTER-GROUNDUP-2"
EXPECTED_ZIP_SHA256="db2d9f70a83302ec56380104f9b163490b10717e16fd8849e9cd6c8205745409"
IMAGE="quant-nova:3.0.0-master-groundup-2-${EXPECTED_ZIP_SHA256:0:12}"
APP_DIR="${NOVA_APP_DIR:-$HOME/quant-nova}"
ENV_FILE="$APP_DIR/.env"
DATA_DIR="$APP_DIR/data"
CONTAINER="quant-nova"
NETWORK="kiwoom-net"
HOST_PORT="${NOVA_HOST_PORT:-3200}"
STAMP="$(date +%Y%m%d%H%M%S)"
BACKUP="quant-nova-backup-master-groundup-2-${STAMP}"
CANDIDATE="quant-nova-candidate-master-groundup-2-${STAMP}"
TMP="$(mktemp -d)"
ZIP="$TMP/QUANT_NOVA_3.0.0_MASTER_GROUNDUP_2.zip"
SRC="$TMP/nova3000g2"
CAND_DATA="$TMP/candidate-data"
DEPLOY_DIR="$APP_DIR/deployments/nova3000-master-groundup-2-$STAMP"
GUARD_STATIC="$APP_DIR/http-guard-v2/static"
GUARD_CACHE="$APP_DIR/http-guard-v2/cache"
GUARD_BK="$DEPLOY_DIR/http-guard-before"
OLD_EXISTS=0; OLD_STOPPED=0; OLD_RENAMED=0; NEW_STARTED=0; GUARD_SYNCED=0; SUCCESS=0
MARKET_ACTIVE=0; REAL_FEED_STATUS="PENDING_NOT_CHECKED"

say(){ printf '\n==> %s\n' "$*"; }
die(){ echo "ERROR: $*" >&2; exit 1; }

rollback(){
  local ec=$?
  trap - EXIT
  if [[ $SUCCESS -eq 1 ]]; then rm -rf "$TMP"; exit 0; fi
  echo "[AUTO-ROLLBACK] Ground-Up 2 배포 미완료 — 기존 immutable active 복구" >&2
  if [[ $NEW_STARTED -eq 1 ]] && sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
    timeout 15 sudo docker stop -t 5 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
    sudo docker rm -f "$CONTAINER" >/dev/null 2>&1 || true
  fi
  sudo docker rm -f "$CANDIDATE" >/dev/null 2>&1 || true
  if [[ $OLD_RENAMED -eq 1 ]] && sudo docker inspect "$BACKUP" >/dev/null 2>&1; then
    sudo docker rename "$BACKUP" "$CONTAINER" >/dev/null 2>&1 || true
    sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
  elif [[ $OLD_EXISTS -eq 1 ]] && sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
    sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
  fi
  if [[ $GUARD_SYNCED -eq 1 && -d "$GUARD_BK" && -d "$GUARD_STATIC" ]]; then
    sudo find "$GUARD_STATIC" -mindepth 1 -maxdepth 1 -type f -delete >/dev/null 2>&1 || true
    sudo cp -a "$GUARD_BK"/. "$GUARD_STATIC"/ >/dev/null 2>&1 || true
    [[ -d "$GUARD_CACHE" ]] && sudo find "$GUARD_CACHE" -mindepth 1 -maxdepth 1 -type f -delete >/dev/null 2>&1 || true
  fi
  rm -rf "$TMP"
  exit "${ec:-1}"
}
trap rollback EXIT

[[ "${EUID:-$(id -u)}" -ne 0 ]] || die "root로 실행하지 마십시오. ubuntu 사용자에서 실행하세요."
for x in sudo python3 sha256sum base64 curl timeout free df du cp awk grep date; do command -v "$x" >/dev/null || die "$x 없음"; done
sudo docker version >/dev/null 2>&1 || die "Docker 접근 실패"
[[ -d "$APP_DIR" ]] || die "$APP_DIR 없음"
[[ -s "$ENV_FILE" ]] || die "$ENV_FILE 없음/비어 있음"
[[ -d "$DATA_DIR" ]] || die "$DATA_DIR 없음"
[[ -r "$DATA_DIR" && -w "$DATA_DIR" && -x "$DATA_DIR" ]] || die "$DATA_DIR 를 현재 ubuntu UID가 읽기/쓰기/탐색할 수 없음 — active 데이터 권한을 임의 변경하지 않고 중단합니다."
mkdir -p "$DEPLOY_DIR"

say "1/16 Embedded source integrity + closed manifest"
