ACTUAL="$(sha256sum "$ZIP" | awk '{print $1}')"
[[ "$ACTUAL" == "$EXPECTED_ZIP_SHA256" ]] || die "embedded ZIP SHA mismatch: $ACTUAL"
python3 - "$ZIP" "$TMP" <<'PY'
import sys,zipfile
z,d=sys.argv[1:]
with zipfile.ZipFile(z) as f:
    bad=f.testzip()
    if bad: raise SystemExit('ZIP CRC fail: '+bad)
    names=f.namelist()
    if not names or any(n.startswith('/') or '..' in n.split('/') for n in names): raise SystemExit('unsafe ZIP path')
    roots={n.split('/')[0] for n in names if n}
    if roots!={'nova3000g2'}: raise SystemExit('unexpected ZIP root: '+repr(roots))
    f.extractall(d)
print('ZIP_CRC_PATH_ROOT=PASS')
PY
[[ -d "$SRC" ]] || die "source root nova3000g2 없음"
( cd "$SRC" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null ) || die "SOURCE_MANIFEST 검증 실패"
python3 - "$SRC" <<'PY'
from pathlib import Path
import sys
r=Path(sys.argv[1]); listed=set()
for line in (r/'SOURCE_MANIFEST.sha256').read_text().splitlines():
    if not line.strip(): continue
    listed.add(line.split('  ',1)[1])
actual={p.relative_to(r).as_posix() for p in r.rglob('*') if p.is_file() and p.name!='SOURCE_MANIFEST.sha256'}
assert listed==actual,(sorted(actual-listed),sorted(listed-actual))
print('SOURCE_MANIFEST_CLOSED_WORLD=PASS files='+str(len(actual)))
PY

say "2/16 Ground-up architecture + frozen BUY policy contract"
python3 - "$SRC" <<'PY'
from pathlib import Path
import json,sys,ast
r=Path(sys.argv[1]); df=(r/'Dockerfile').read_text(); assert df.startswith('FROM python:3.12-slim-bookworm')
assert 'FROM quant-nova' not in df and 'docker commit' not in df
text='\n'.join(p.read_text(errors='ignore') for p in list((r/'app').rglob('*.py'))+list((r/'static').rglob('*')) if p.is_file())
for bad in ('maxlen=1500','main.py.bak','ROOT-MEMORY-LIVENESS','CLEAN-RUNTIME-R1.','MASTER-GROUNDUP-1','sed -i','docker commit'):
    assert bad not in text,bad
j=json.loads((r/'SIGNAL_POLICY_FROZEN.json').read_text())
assert j['policy']=='ENTRY_V18_TRUTH_GUARD_MAX_PROFIT'
assert j['pressure_score']==62 and j['hold_sec']==8 and j['cooldown_sec']==600
assert j['pullback_pct_min']==0.12 and j['pullback_pct_max']==2.0 and j['direct']['score']==75
cfg=(r/'app/config.py').read_text(); assert 'NOVA-3.0.0-MASTER-GROUNDUP-2' in cfg and 'nova30g2' in cfg
print('GROUNDUP2_CONTRACT=PASS')
PY

say "3/16 Existing active + credentials + host safety preflight"
python3 - "$ENV_FILE" <<'PY'
import sys
vals={}
for raw in open(sys.argv[1],encoding='utf-8',errors='ignore'):
    line=raw.strip()
    if not line or line.startswith('#'): continue
    if line.startswith('export '): line=line[7:].lstrip()
    if '=' not in line: continue
    k,v=line.split('=',1); k=k.strip(); v=v.strip()
    if len(v)>=2 and v[0]==v[-1] and v[0] in "'\"": v=v[1:-1]
    vals[k]=v.strip()
assert vals.get('KIWOOM_APP_KEY'),'KIWOOM_APP_KEY missing/empty'
assert vals.get('KIWOOM_SECRET_KEY') or vals.get('KIWOOM_APP_SECRET'),'KIWOOM_SECRET_KEY/KIWOOM_APP_SECRET missing/empty'
print('ENV_CREDENTIAL_CONTRACT=PASS')
PY
if sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then OLD_EXISTS=1; fi
[[ $OLD_EXISTS -eq 1 ]] || die "기존 quant-nova 컨테이너 없음 — 안전 rollback 기준선이 필요합니다."
OLD_STATUS="$(sudo docker inspect -f '{{.State.Status}}' "$CONTAINER")"
[[ "$OLD_STATUS" == "running" ]] || die "기존 quant-nova가 running 상태가 아님: $OLD_STATUS"
OLD_IMAGE_ID="$(sudo docker inspect -f '{{.Image}}' "$CONTAINER")"
DATA_KB="$(du -sk "$DATA_DIR" | awk '{print $1}')"
FREE_KB="$(df -Pk "$APP_DIR" | awk 'NR==2{print $4}')"
NEED_KB=$(( DATA_KB * 2 + 1800000 ))
(( FREE_KB > NEED_KB )) || die "디스크 여유 부족: free=${FREE_KB}KB need>${NEED_KB}KB"
printf 'HOST_PREFLIGHT=PASS old_image=%s data_kb=%s free_kb=%s\n' "$OLD_IMAGE_ID" "$DATA_KB" "$FREE_KB"

say "4/16 Freeze existing active — stop only, no rename/delete/mutation"
timeout 20 sudo docker stop -t 8 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || die "기존 active 정지 실패"
[[ "$(sudo docker inspect -f '{{.State.Running}}' "$CONTAINER")" == "false" ]] || die "기존 active가 아직 실행 중"
OLD_STOPPED=1
AVAIL_MB=0
for _ in $(seq 1 30); do AVAIL_MB="$(free -m | awk '/Mem:/{print $7}')"; (( AVAIL_MB >= 280 )) && break; sleep 1; done
(( AVAIL_MB >= 280 )) || die "기존 active 정지 후 available RAM ${AVAIL_MB}MB < 280MB"
echo "OLD_ACTIVE_FROZEN=PASS available=${AVAIL_MB}MB"

say "5/16 Frozen production-data snapshot after stop"
mkdir -p "$CAND_DATA"
sudo cp -a "$DATA_DIR"/. "$CAND_DATA"/
sudo mkdir -p "$CAND_DATA/nova30g2"
sudo chown -R "$(id -u):$(id -g)" "$CAND_DATA"
echo "DATA_SNAPSHOT=PASS size=$(du -sh "$CAND_DATA" | awk '{print $1}')"

say "6/16 Clean Docker build from Python base"
export DOCKER_BUILDKIT=1
sudo docker build --pull --no-cache -t "$IMAGE" "$SRC"
IMAGE_ID="$(sudo docker image inspect -f '{{.Id}}' "$IMAGE")"
[[ -n "$IMAGE_ID" ]] || die "clean image build 실패"
sudo docker run --rm --entrypoint python "$IMAGE" -c "from app.config import SETTINGS; assert SETTINGS.version=='NOVA-3.0.0-MASTER-GROUNDUP-2'; assert str(SETTINGS.data_dir).endswith('nova30g2'); print('IMAGE_IDENTITY=PASS')"
echo "CLEAN_IMAGE=$IMAGE_ID"

NET_ARGS=()
if sudo docker network inspect "$NETWORK" >/dev/null 2>&1; then NET_ARGS=(--network "$NETWORK"); fi
UIDGID="$(id -u):$(id -g)"
COMMON=(--read-only --tmpfs /tmp:rw,noexec,nosuid,size=32m --user "$UIDGID" --env-file "$ENV_FILE" -e NOVA_DATA_DIR=/app/data/nova30g2 -e NOVA_LEGACY_DATA_DIR=/app/data --pids-limit 256 --security-opt no-new-privileges --cap-drop ALL --log-driver json-file --log-opt max-size=10m --log-opt max-file=3)

say "7/16 Isolated candidate on frozen production-data copy"
sudo docker rm -f "$CANDIDATE" >/dev/null 2>&1 || true
sudo docker run -d --name "$CANDIDATE" "${NET_ARGS[@]}" "${COMMON[@]}" --memory=384m --memory-swap=384m --memory-reservation=256m -e NOVA_CANDIDATE_MODE=1 -e NOVA_OFFLINE=0 -v "$CAND_DATA:/app/data" "$IMAGE" >/dev/null
for _ in $(seq 1 120); do
  if sudo docker exec "$CANDIDATE" python -c "import json,urllib.request,sys;j=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/readyz',timeout=2));sys.exit(0 if j.get('ok') else 1)" >/dev/null 2>&1; then break; fi
  sleep .5
done
sudo docker exec "$CANDIDATE" python -c "import json,urllib.request;j=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/readyz',timeout=2));assert j.get('ok'),j;assert j.get('restore_ok') is True,j;assert not j.get('journal_init_error'),j;print('CANDIDATE_READYZ=PASS',j)"
sudo docker exec "$CANDIDATE" env PYTHONPATH=/app python /app/scripts/runtime_smoke.py --clients 10 --ready-timeout 10
sudo docker exec "$CANDIDATE" env PYTHONPATH=/app python /app/scripts/master_audit.py
sudo docker exec "$CANDIDATE" env PYTHONPATH=/app python /app/scripts/validate.py --quick
CMEM="$(sudo docker inspect -f '{{.HostConfig.Memory}} {{.HostConfig.MemorySwap}}' "$CANDIDATE")"
[[ "$(awk '{print $1}' <<<"$CMEM")" == "$(awk '{print $2}' <<<"$CMEM")" ]] || die "candidate no-swap cgroup 불일치: $CMEM"

say "8/16 Candidate 60-second memory/journal/queue/UI soak"
sudo docker exec -i "$CANDIDATE" python - <<'PY'
import json,os,time,urllib.request,statistics
T=os.getenv('APP_ACCESS_TOKEN','').strip(); H={'X-App-Token':T} if T else {}
def get(path):
    with urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8000'+path,headers=H),timeout=3) as r:return json.load(r)
rss=[]
for _ in range(30):
    j=get('/api/realtime-health'); m=j.get('memory') or {}; t=j.get('telemetry') or {}; w=j.get('journal') or {}
    assert j.get('ok'),j; assert float(m.get('swap_mb') or 0)==0,m; assert float(m.get('rss_mb') or 0)<350,m
    assert int(j.get('coalesced_errors') or 0)==0,j
    for k in ('db_init_fail','critical_failed','important_enqueue_fail','wal_hard_stall_exit','event_hard_stall_exit','noncritical_write_error'):
        assert int(w.get(k) or 0)==0,(k,w.get(k))
    for k in ('dropped_signal_tick_count','signal_price_mismatch_count','wrong_venue_price_count','signal_without_live_snapshot_count','protected_dirty_overflow_count','pinned_ws_overflow','followup_ws_overflow','restore_error_count','restore_wal_error_count'):
        assert int(t.get(k) or 0)==0,(k,t.get(k))
    rss.append(float(m.get('rss_mb') or 0)); time.sleep(2)
assert statistics.mean(rss[-10:])-statistics.mean(rss[:10])<50,(rss[:10],rss[-10:])
print('CANDIDATE_SOAK=PASS',{'rss_start':rss[0],'rss_end':rss[-1],'rss_max':max(rss)})
PY
[[ "$(sudo docker inspect -f '{{.State.OOMKilled}}' "$CANDIDATE")" == "false" ]] || die "candidate OOMKilled"
[[ "$(sudo docker inspect -f '{{.RestartCount}}' "$CANDIDATE")" == "0" ]] || die "candidate restarted"
sudo docker rm -f "$CANDIDATE" >/dev/null

say "9/16 Atomic cutover — old container renamed only after candidate PASS"
sudo docker rename "$CONTAINER" "$BACKUP"; OLD_RENAMED=1
sudo docker run -d --name "$CONTAINER" "${NET_ARGS[@]}" "${COMMON[@]}" --restart unless-stopped --memory=448m --memory-swap=448m --memory-reservation=320m -e NOVA_CANDIDATE_MODE=0 -e NOVA_OFFLINE=0 -p "${HOST_PORT}:8000" -v "$DATA_DIR:/app/data" "$IMAGE" >/dev/null
NEW_STARTED=1
for _ in $(seq 1 120); do
  curl -fsS --max-time 2 "http://127.0.0.1:${HOST_PORT}/api/livez" >/dev/null 2>&1 && break
  sleep .5
done
curl -fsS --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/livez" | python3 -c 'import json,sys;j=json.load(sys.stdin);assert j.get("ok"),j;assert j.get("version")=="NOVA-3.0.0-MASTER-GROUNDUP-2",j;print("ACTIVE_LIVEZ=PASS",j)'
for _ in $(seq 1 120); do
  sudo docker exec "$CONTAINER" python -c "import json,urllib.request,sys;j=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/readyz',timeout=2));sys.exit(0 if j.get('ok') else 1)" >/dev/null 2>&1 && break
  sleep .5
done
sudo docker exec "$CONTAINER" python -c "import json,urllib.request;j=json.load(urllib.request.urlopen('http://127.0.0.1:8000/api/readyz',timeout=2));assert j.get('ok') and j.get('restore_ok'),j;print('ACTIVE_READYZ=PASS',j)"
AMEM="$(sudo docker inspect -f '{{.HostConfig.Memory}} {{.HostConfig.MemorySwap}}' "$CONTAINER")"
[[ "$(awk '{print $1}' <<<"$AMEM")" == "$(awk '{print $2}' <<<"$AMEM")" ]] || die "active no-swap cgroup 불일치: $AMEM"

say "10/16 Active HTTP + 10-client UI WebSocket smoke"
sudo docker exec "$CONTAINER" env PYTHONPATH=/app python /app/scripts/runtime_smoke.py --clients 10 --ready-timeout 10
curl -fsS --max-time 3 "http://127.0.0.1:${HOST_PORT}/" >/dev/null
echo "ACTIVE_HTTP_UI_WS=PASS"

say "11/16 Real Kiwoom feed gate when market is active"
MARKET_ACTIVE="$(sudo docker exec "$CONTAINER" python -c "from app.runtime.clock import sessions;print('1' if sessions()['active'] else '0')")"
if [[ "$MARKET_ACTIVE" == "1" ]]; then
  OK=0
  for _ in $(seq 1 150); do
    if sudo docker exec -i "$CONTAINER" python - <<'PY' >/dev/null 2>&1
import json,os,time,urllib.request
T=os.getenv('APP_ACCESS_TOKEN','').strip();H={'X-App-Token':T} if T else {}
with urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8000/api/realtime-health',headers=H),timeout=3) as r:j=json.load(r)
w=j.get('ws') or {};m=j.get('memory') or {};t=j.get('telemetry') or {};q=j.get('journal') or {};s=j.get('sessions') or {}
assert s.get('active') and s.get('calendar_known'),s
assert j.get('feed_state')=='LIVE',j.get('feed_state')
assert w.get('connected') and w.get('logged_in') and int(w.get('registered') or 0)>0,w
assert time.time()-float(w.get('last_message_at') or 0)<8,w
assert time.time()-float(w.get('last_trade_at') or 0)<12,w
assert float(m.get('swap_mb') or 0)==0,m
for k in ('dropped_signal_tick_count','signal_price_mismatch_count','wrong_venue_price_count','signal_without_live_snapshot_count','tracking_capacity_reject_count','pinned_ws_overflow','followup_ws_overflow'):
    assert int(t.get(k) or 0)==0,(k,t.get(k))
for k in ('db_init_fail','critical_failed','important_enqueue_fail','wal_hard_stall_exit','event_hard_stall_exit','noncritical_write_error'):
    assert int(q.get(k) or 0)==0,(k,q.get(k))
PY
    then OK=1; break; fi
    sleep 2
  done
  [[ $OK -eq 1 ]] || die "실장중 Kiwoom WS/Feed LIVE gate 실패"
  REAL_FEED_STATUS="PASS"; echo "REAL_FEED_GATE=PASS"
else
  REAL_FEED_STATUS="PENDING_MARKET_OPEN"; echo "REAL_FEED_GATE=PENDING_MARKET_OPEN (market closed)"
fi

say "12/16 Five-minute full-worker hard gate"
sudo docker exec -i "$CONTAINER" python - <<'PY'
import json,os,time,urllib.request,statistics
T=os.getenv('APP_ACCESS_TOKEN','').strip();H={'X-App-Token':T} if T else {}
def get():
    with urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8000/api/realtime-health',headers=H),timeout=3) as r:return json.load(r)
rss=[];start=time.time()
for _ in range(60):
    j=get();m=j.get('memory') or {};t=j.get('telemetry') or {};w=j.get('journal') or {};s=j.get('sessions') or {};ws=j.get('ws') or {}
    assert j.get('ok'),j; assert float(m.get('swap_mb') or 0)==0,m; assert float(m.get('rss_mb') or 0)<400,m
    assert float(j.get('event_loop_lag_p95_ms') or 0)<300,j.get('event_loop_lag_p95_ms')
    assert float(j.get('trade_queue_oldest_age_ms') or 0)<1000,j.get('trade_queue_oldest_age_ms')
    assert int(j.get('coalesced_errors') or 0)==0,j
    for k in ('dropped_signal_tick_count','signal_price_mismatch_count','wrong_venue_price_count','signal_without_live_snapshot_count','protected_dirty_overflow_count','tracking_capacity_reject_count','pinned_ws_overflow','followup_ws_overflow','restore_error_count','restore_wal_error_count'):
        assert int(t.get(k) or 0)==0,(k,t.get(k))
    for k in ('db_init_fail','critical_failed','important_enqueue_fail','wal_hard_stall_exit','event_hard_stall_exit','noncritical_write_error'):
        assert int(w.get(k) or 0)==0,(k,w.get(k))
    if s.get('active'):
        assert j.get('feed_state')=='LIVE',j.get('feed_state')
        assert ws.get('connected') and ws.get('logged_in') and int(ws.get('registered') or 0)>0,ws
        assert time.time()-float(ws.get('last_message_at') or 0)<8,ws
        assert time.time()-float(ws.get('last_trade_at') or 0)<12,ws
    rss.append(float(m.get('rss_mb') or 0));time.sleep(5)
first=statistics.mean(rss[:12]);last=statistics.mean(rss[-12:]);assert last-first<80,(first,last,max(rss))
print('ACTIVE_5MIN_SOAK=PASS',{'rss_first60_avg':round(first,1),'rss_last60_avg':round(last,1),'rss_max':max(rss),'seconds':round(time.time()-start)})
PY
[[ "$(sudo docker inspect -f '{{.State.OOMKilled}}' "$CONTAINER")" == "false" ]] || die "active OOMKilled"
[[ "$(sudo docker inspect -f '{{.RestartCount}}' "$CONTAINER")" == "0" ]] || die "active restarted during gate"

say "13/16 Static UI atomic guard sync (app runtime source untouched)"
if [[ -d "$GUARD_STATIC" ]]; then
  mkdir -p "$GUARD_BK"
  sudo cp -a "$GUARD_STATIC"/. "$GUARD_BK"/ || die "HTTP guard static backup 실패"
  GUARD_SYNCED=1
  for f in index.html nova.js nova.css manifest.webmanifest sw.js; do
    [[ -f "$SRC/static/$f" ]] || continue
    sudo cp "$SRC/static/$f" "$GUARD_STATIC/.$f.nova30g2.tmp"
    sudo chmod 644 "$GUARD_STATIC/.$f.nova30g2.tmp"
    sudo mv "$GUARD_STATIC/.$f.nova30g2.tmp" "$GUARD_STATIC/$f"
  done
  [[ -d "$GUARD_CACHE" ]] && sudo find "$GUARD_CACHE" -mindepth 1 -maxdepth 1 -type f -delete >/dev/null 2>&1 || true
  echo "HTTP_GUARD_STATIC_SYNC=PASS"
else
  echo "HTTP_GUARD_STATIC_SYNC=SKIP(no guard static dir)"
fi
for helper in nova-http-guard kiwoom-caddy; do
  if sudo docker inspect "$helper" >/dev/null 2>&1; then
    [[ "$(sudo docker inspect -f '{{.State.Running}}' "$helper")" == "true" ]] || die "$helper not running"
    echo "$helper=RUNNING"
  fi
done

say "14/16 Create read-only next-market live-feed verifier"
cat > "$DEPLOY_DIR/verify-live-feed.sh" <<'VERIFY'
#!/usr/bin/env bash
set -Eeuo pipefail
C="quant-nova"
sudo docker inspect "$C" >/dev/null 2>&1 || { echo "FAIL: quant-nova missing"; exit 1; }
[[ "$(sudo docker inspect -f '{{.State.Running}}' "$C")" == "true" ]] || { echo "FAIL: quant-nova not running"; exit 1; }
sudo docker exec -i "$C" python - <<'PY'
import json,os,time,urllib.request,sys
T=os.getenv('APP_ACCESS_TOKEN','').strip();H={'X-App-Token':T} if T else {}
def get(p):
    with urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8000'+p,headers=H),timeout=3) as r:return json.load(r)
r=get('/api/readyz');assert r.get('ok') and r.get('restore_ok'),r
j=get('/api/realtime-health');s=j.get('sessions') or {};w=j.get('ws') or {};m=j.get('memory') or {};t=j.get('telemetry') or {};q=j.get('journal') or {}
if not s.get('active'):
    print('PENDING: market closed; run during KRX/NXT live session');sys.exit(3)
assert s.get('calendar_known'),s
assert j.get('feed_state')=='LIVE',j.get('feed_state')
assert w.get('connected') and w.get('logged_in') and int(w.get('registered') or 0)>0,w
assert time.time()-float(w.get('last_message_at') or 0)<8,w
assert time.time()-float(w.get('last_trade_at') or 0)<12,w
assert float(m.get('swap_mb') or 0)==0,m;assert float(m.get('rss_mb') or 0)<400,m
assert float(j.get('event_loop_lag_p95_ms') or 0)<300,j.get('event_loop_lag_p95_ms')
assert float(j.get('trade_queue_oldest_age_ms') or 0)<1000,j.get('trade_queue_oldest_age_ms')
assert int(j.get('coalesced_errors') or 0)==0,j
for k in ('dropped_signal_tick_count','signal_price_mismatch_count','wrong_venue_price_count','signal_without_live_snapshot_count','tracking_capacity_reject_count','pinned_ws_overflow','followup_ws_overflow','restore_error_count','restore_wal_error_count'):
    assert int(t.get(k) or 0)==0,(k,t.get(k))
for k in ('db_init_fail','critical_failed','important_enqueue_fail','wal_hard_stall_exit','event_hard_stall_exit','noncritical_write_error'):
    assert int(q.get(k) or 0)==0,(k,q.get(k))
print('LIVE_FEED_VERIFICATION=PASS',{'feed_state':j.get('feed_state'),'registered':w.get('registered'),'rss_mb':m.get('rss_mb'),'swap_mb':m.get('swap_mb')})
PY
VERIFY
chmod 700 "$DEPLOY_DIR/verify-live-feed.sh"
echo "LIVE_FEED_VERIFIER=$DEPLOY_DIR/verify-live-feed.sh"

